/* --- 5. data.json product loader ---
   Edit data.json to swap the product catalog.
   After viewer.js renders, you can use window.__siteData
   to update product elements in the DOM. ---- */
(async function loadData() {
  try {
    const res = await fetch('./data.json');
    if (!res.ok) throw new Error('Could not load data.json');
    const data = await res.json();
    window.__siteData = data;

    /* Example: inject product data after viewer renders.
       viewer.js fires a custom event when ready — hook into it:
       document.addEventListener('rm:ready', () => {
         data.products.forEach(p => {
           // locate product elements and update text/images
         });
       }); */
  } catch (e) {
    console.warn('[site] data.json not loaded:', e.message);
  }
})();
